"""Expanded Library of Congress Subject Headings (LCSH) Taxonomy.

Provides hierarchical broader, narrower, and related subject relationships.
"""

from typing import Dict, List, Optional
from dataclasses import dataclass, field


@dataclass
class LcshTaxonomyNode:
    subject_id: str
    preferred_term: str
    class_number: str
    parent_terms: List[str] = field(default_factory=list)
    child_terms: List[str] = field(default_factory=list)
    scope: str = ""


LCSH_TAXONOMY: Dict[str, LcshTaxonomyNode] = {}

def _tax(sid: str, term: str, cl: str, parents: List[str], children: List[str], scope: str):
    LCSH_TAXONOMY[sid] = LcshTaxonomyNode(sid, term, cl, parents, children, scope)

