def lookup_taxonomy_node(term_or_id: str) -> Optional[LcshTaxonomyNode]:
    clean = term_or_id.strip().lower()
    for node in LCSH_TAXONOMY.values():
        if node.subject_id.lower() == clean or node.preferred_term.lower() == clean:
            return node
    return None
